def getApiOverview(id, **_extra):
    import json, os, datetime, re, hashlib
    from urllib.parse import urlsplit, urlunsplit

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0238000" if __import__("os").path.isdir("./environment_mix/0238000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.getpid()}_{hashlib.sha256(os.urandom(16)).hexdigest()[:10]}"

    def _load_rows(filename):
        data = _load(filename)
        if isinstance(data, dict) and isinstance(data.get("rows"), list):
            return data, data["rows"]
        if isinstance(data, list):
            return {"rows": data}, data
        return {"rows": []}, []

    def _save_rows(filename, container, rows):
        if isinstance(container, dict):
            container["rows"] = rows
            _save(filename, container)
        else:
            _save(filename, rows)

    def _ensure_request_logs():
        cont, rows = _load_rows("request_logs.json")
        return cont, rows

    def _log(status, resolution_id=None, api_spec_id=None, error_code=None):
        cont, rows = _ensure_request_logs()
        ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
        rows.append({
            "id": _new_id("req"),
            "endpoint": "getApiOverview",
            "timestamp": _now(),
            "latency_ms": ms,
            "status": status,
            "resolution_id": resolution_id,
            "api_spec_id": api_spec_id,
            "error_code": error_code
        })
        _save_rows("request_logs.json", cont, rows)

    # Quota/rate limiting: only if datastore defines it; otherwise no-op.
    def _enforce_limits():
        cont, rows = _load_rows("request_logs.json")
        # If there is a separate quotas file in some deployments, enforce it; otherwise no-op.
        q = _load("quotas.json")
        if isinstance(q, dict) and q:
            # expected (best-effort): {"per_minute": int, "per_day": int}
            per_min = q.get("per_minute")
            per_day = q.get("per_day")
            now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
            def _parse(ts):
                try:
                    if isinstance(ts, str) and ts.endswith("Z"):
                        return datetime.datetime.fromisoformat(ts[:-1]).replace(tzinfo=datetime.timezone.utc)
                except Exception:
                    return None
                return None
            if isinstance(rows, list):
                if isinstance(per_min, int) and per_min >= 0:
                    cutoff = now - datetime.timedelta(minutes=1)
                    used = 0
                    for r in rows:
                        t = _parse(r.get("timestamp"))
                        if t and t >= cutoff:
                            used += 1
                    if used >= per_min:
                        return _err("RATE_LIMIT", "Rate limit exceeded.")
                if isinstance(per_day, int) and per_day >= 0:
                    cutoff = now - datetime.timedelta(days=1)
                    used = 0
                    for r in rows:
                        t = _parse(r.get("timestamp"))
                        if t and t >= cutoff:
                            used += 1
                    if used >= per_day:
                        return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    def _detect_kind(raw):
        s = raw.strip()
        try:
            sp = urlsplit(s)
        except Exception:
            sp = None
        if sp and sp.scheme and sp.netloc:
            return "url"
        # accept existing IDs including underscores and mixed case
        if re.match(r"^[A-Za-z0-9][A-Za-z0-9_.-]{0,255}$", s):
            return "catalog_id"
        return "unknown"

    def _canon_catalog_id(raw):
        s = (raw or "").strip()
        if not s:
            return None
        # keep internal characters but normalize case and remove whitespace
        s = re.sub(r"\s+", "", s).lower()
        if not s:
            return None
        if re.match(r"^[a-z0-9][a-z0-9_.-]{0,255}$", s) is None:
            return None
        return s

    def _canon_url(raw):
        s = (raw or "").strip()
        try:
            sp = urlsplit(s)
        except Exception:
            return None, "invalid URL for spec source"
        scheme = (sp.scheme or "").lower()
        if scheme not in ("http", "https"):
            return None, "invalid URL for spec source: only http/https supported"
        if not sp.netloc:
            return None, "invalid URL for spec source: missing host"
        # policy observed in datastore: disallow query and fragments for raw spec URLs
        if sp.fragment:
            return None, "invalid URL for spec source: fragments are not permitted"
        if sp.query:
            return None, "canonical URL mismatch: query params not allowed for spec source"
        canon = urlunsplit((scheme, sp.netloc, sp.path or "/", "", ""))
        return canon, None

    def _find_spec_by_any_id(raw_id):
        specs_cont, specs = _load_rows("api_specs.json")
        rid = (raw_id or "").strip()
        if not rid:
            return None, specs_cont, specs
        # try direct id match first
        for s in specs:
            if s.get("id") == rid:
                return s, specs_cont, specs
        # if looks like our IDs, also try external_id match (case-insensitive)
        rid_l = rid.lower()
        for s in specs:
            ext = s.get("external_id")
            if isinstance(ext, str) and ext.lower() == rid_l:
                return s, specs_cont, specs
        return None, specs_cont, specs

    def _get_overview_for_spec(api_spec_id):
        ovw_cont, ovws = _load_rows("api_overviews.json")
        candidates = [o for o in ovws if o.get("api_spec_id") == api_spec_id and o.get("status") in ("active", "stale", "error")]
        if not candidates:
            return None
        # prefer active over stale over error; tie-breaker updated_at
        prio = {"active": 2, "stale": 1, "error": 0}
        def key(o):
            ua = o.get("updated_at") or o.get("created_at") or ""
            return (prio.get(o.get("status"), -1), ua)
        candidates.sort(key=key, reverse=True)
        return candidates[0]

    def _count_operations(api_spec_id):
        op_cont, ops = _load_rows("api_operations.json")
        return sum(1 for op in ops if op.get("api_spec_id") == api_spec_id and op.get("status") != "removed")

    # Validate input
    if not isinstance(id, str) or not id.strip():
        err = _err("VALIDATION_ERROR", "`id` is required and must be a non-empty string.")
        _log("error", error_code=err["error"]["code"])
        return err

    lim = _enforce_limits()
    if lim:
        _log("error", error_code=lim["error"]["code"])
        return lim

    raw = id.strip()
    detected = _detect_kind(raw)

    # Resolution: use existing spec if caller passed internal spec id or external_id
    existing_spec, specs_cont, specs = _find_spec_by_any_id(raw)
    res_cont, resolutions = _load_rows("api_resolutions.json")

    # If direct spec found, create/refresh a resolution row that points to it (idempotent-ish on normalized_input)
    if existing_spec:
        normalized_input = (raw.lower() if detected != "url" else raw)
        # canonical normalization: for catalog ids use lower; for url use canon_url if possible
        if detected == "catalog_id":
            ci = _canon_catalog_id(raw)
            normalized_input = ci if ci is not None else normalized_input
        elif detected == "url":
            cu, cu_err = _canon_url(raw)
            normalized_input = cu if cu is not None else raw

        # Find an existing resolution by normalized_input
        found_res = None
        for r in resolutions:
            if r.get("normalized_input") == normalized_input and r.get("resolved") is True and r.get("api_spec_id") == existing_spec.get("id"):
                found_res = r
                break
        if not found_res:
            now = _now()
            found_res = {
                "id": _new_id("oamcp_res"),
                "input_id": raw,
                "normalized_input": normalized_input,
                "detected_kind": detected if detected in ("catalog_id", "url") else "unknown",
                "api_spec_id": existing_spec.get("id"),
                "resolved": True,
                "resolution_error": None,
                "created_at": now,
                "updated_at": now
            }
            resolutions.append(found_res)
            _save_rows("api_resolutions.json", res_cont, resolutions)

        # Serve overview if possible (do NOT create a new spec if the caller provided a known spec id)
        api_spec = existing_spec
        api_spec_id = api_spec.get("id")

        # If not ready, return a non-ready response (do not error CONFLICT); this is consistent with observed service policy
        if api_spec.get("status") != "ready":
            body = {
                "resolution": found_res,
                "api_spec": api_spec,
                "overview": None,
                "status": "not_ready",
                "message": "API spec is not ready yet."
            }
            _log("ok", resolution_id=found_res.get("id"), api_spec_id=api_spec_id)
            return body

        overview = _get_overview_for_spec(api_spec_id)
        # If spec is ready but overview missing, treat as not found
        if not overview:
            err = _err("NOT_FOUND", "API overview is not available for this spec.", api_spec_id=api_spec_id, resolution=found_res, api_spec=api_spec)
            _log("error", resolution_id=found_res.get("id"), api_spec_id=api_spec_id, error_code=err["error"]["code"])
            return err

        # ensure operation_count consistency with non-removed ops
        op_count = _count_operations(api_spec_id)
        if isinstance(overview, dict):
            # do not mutate stored overview here; return corrected view
            overview_out = dict(overview)
            overview_out["operation_count"] = op_count
        else:
            overview_out = overview

        out = {
            "resolution": found_res,
            "api_spec": api_spec,
            "overview": overview_out
        }
        _log("ok", resolution_id=found_res.get("id"), api_spec_id=api_spec_id)
        return out

    # Otherwise: resolve by kind and canonical key; may create spec
    now = _now()
    resolution = {
        "id": _new_id("oamcp_res"),
        "input_id": raw,
        "normalized_input": None,
        "detected_kind": detected if detected in ("catalog_id", "url") else "unknown",
        "api_spec_id": None,
        "resolved": False,
        "resolution_error": None,
        "created_at": now,
        "updated_at": now
    }

    canonical = None
    if detected == "catalog_id":
        canon_id = _canon_catalog_id(raw)
        if canon_id is None:
            resolution["normalized_input"] = raw.strip().lower()
            resolution["resolution_error"] = "unrecognized identifier: not a catalog key and not a valid http(s) URL"
        else:
            canonical = f"catalog:{canon_id}"
            resolution["normalized_input"] = canon_id
    elif detected == "url":
        canon_u, uerr = _canon_url(raw)
        if canon_u is None:
            resolution["normalized_input"] = raw
            resolution["resolution_error"] = uerr
        else:
            canonical = f"url:{canon_u}"
            resolution["normalized_input"] = canon_u
    else:
        resolution["normalized_input"] = raw.strip()
        resolution["resolution_error"] = "unrecognized identifier: not a catalog key and not a valid http(s) URL"

    if canonical is None:
        resolutions.append(resolution)
        _save_rows("api_resolutions.json", res_cont, resolutions)
        err = _err("VALIDATION_ERROR", "Unsupported API identifier format.", resolution=resolution)
        _log("error", resolution_id=resolution.get("id"), error_code=err["error"]["code"])
        return err

    # Find existing spec by resolved_canonical_id
    found_spec = None
    for s in specs:
        if s.get("resolved_canonical_id") == canonical:
            found_spec = s
            break

    if not found_spec:
        # Create new spec row and transition new -> fetching (as per rules)
        spec_id = _new_id("oamcp_api")
        source_kind = "catalog_id" if detected == "catalog_id" else "url"
        ext_id = resolution["normalized_input"] if detected == "catalog_id" else None
        src_url = resolution["normalized_input"] if detected == "url" else None
        spec_row = {
            "id": spec_id,
            "external_id": ext_id,
            "source_url": src_url,
            "source_kind": source_kind,
            "resolved_canonical_id": canonical,
            "content_type": None,
            "http_etag": None,
            "http_last_modified": None,
            "last_fetched_at": None,
            "last_parsed_at": None,
            "parse_error": None,
            "spec_sha256": None,
            "openapi_version": None,
            "spec_format": None,
            "status": "fetching",
            "created_at": now,
            "updated_at": now
        }
        specs.append(spec_row)
        _save_rows("api_specs.json", specs_cont, specs)
        found_spec = spec_row

    resolution["api_spec_id"] = found_spec.get("id")
    resolution["resolved"] = True
    resolution["resolution_error"] = None
    resolutions.append(resolution)
    _save_rows("api_resolutions.json", res_cont, resolutions)

    # Return non-ready response if not ready
    if found_spec.get("status") != "ready":
        out = {
            "resolution": resolution,
            "api_spec": found_spec,
            "overview": None,
            "status": "not_ready",
            "message": "API spec is not ready yet."
        }
        _log("ok", resolution_id=resolution.get("id"), api_spec_id=found_spec.get("id"))
        return out

    overview = _get_overview_for_spec(found_spec.get("id"))
    if not overview:
        err = _err("NOT_FOUND", "API overview is not available for this spec.", api_spec_id=found_spec.get("id"), resolution=resolution, api_spec=found_spec)
        _log("error", resolution_id=resolution.get("id"), api_spec_id=found_spec.get("id"), error_code=err["error"]["code"])
        return err

    op_count = _count_operations(found_spec.get("id"))
    overview_out = dict(overview)
    overview_out["operation_count"] = op_count

    out = {"resolution": resolution, "api_spec": found_spec, "overview": overview_out}
    _log("ok", resolution_id=resolution.get("id"), api_spec_id=found_spec.get("id"))
    return out

def listApiOperations(id, query=None, tag=None, method=None, path=None, status=None, includeRemoved=None, page=None, pageSize=None, orderBy=None, order=None, refresh=None, **_extra):
    import json, os, datetime, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0238000" if __import__("os").path.isdir("./environment_mix/0238000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    def _utcnow_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _load_rows(filename):
        data = _load(filename)
        if isinstance(data, dict):
            rows = data.get("rows")
            if isinstance(rows, list):
                return data, rows
            return {"rows": []}, []
        if isinstance(data, list):
            return {"rows": data}, data
        return {"rows": []}, []

    def _save_rows(filename, container, rows):
        if isinstance(container, dict):
            container["rows"] = rows
            _save(filename, container)
        else:
            _save(filename, rows)

    def _new_id(prefix):
        import os as _os, time as _time, secrets as _secrets
        return f"{prefix}_{int(_time.time()*1000)}_{_os.getpid()}_{_secrets.token_hex(8)}"

    def _ensure_logs():
        cont, rows = _load_rows("request_logs.json")
        if not isinstance(rows, list):
            rows = []
        return cont, rows

    def _log(status, resolution_id=None, api_spec_id=None, error_code=None, details=None):
        cont, rows = _ensure_logs()
        latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
        rows.append({
            "id": _new_id("req"),
            "endpoint": "listApiOperations",
            "timestamp": _utcnow_z(),
            "latency_ms": latency_ms,
            "status": status,
            "resolution_id": resolution_id,
            "api_spec_id": api_spec_id,
            "error_code": error_code,
            "details": details or {}
        })
        _save_rows("request_logs.json", cont, rows)

    # ---- validate inputs ----
    if not isinstance(id, str) or not id.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'id' is required and must be a non-empty string.")

    if query is not None and not isinstance(query, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'query' (must be string).")
    if tag is not None and not isinstance(tag, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'tag' (must be string).")
    methods = ("GET", "POST", "PUT", "PATCH", "DELETE", "HEAD", "OPTIONS", "TRACE")
    if method is not None:
        if not isinstance(method, str) or method.upper() not in methods:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid 'method' (must be one of GET/POST/PUT/PATCH/DELETE/HEAD/OPTIONS/TRACE).")
        method = method.upper()
    if path is not None and not isinstance(path, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'path' (must be string).")
    op_statuses = ("active", "stale", "removed")
    if status is not None:
        if not isinstance(status, str) or status not in op_statuses:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid 'status' (must be one of active/stale/removed).")
    if includeRemoved is None:
        includeRemoved = False
    if not isinstance(includeRemoved, bool):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'includeRemoved' (must be boolean).")
    if refresh is None:
        refresh = False
    if not isinstance(refresh, bool):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'refresh' (must be boolean).")

    if page is None:
        page = 1
    if not isinstance(page, int) or page < 1:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'page' (must be integer >= 1).")
    if pageSize is None:
        pageSize = 50
    if not isinstance(pageSize, int) or pageSize < 1 or pageSize > 200:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'pageSize' (must be integer 1..200).")

    if orderBy is None:
        orderBy = "path"
    if orderBy not in ("path", "method", "operation_id", "updated_at"):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'orderBy' (must be one of path/method/operation_id/updated_at).")
    if order is None:
        order = "asc"
    if order not in ("asc", "desc"):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'order' (must be 'asc' or 'desc').")

    raw_id = id.strip()

    # ---- resolve spec (accept internal spec id too) ----
    api_specs_cont, api_specs = _load_rows("api_specs.json")
    res_cont, res_rows = _load_rows("api_resolutions.json")

    def _is_probable_url(s):
        return re.match(r"^https?://", s.strip(), re.IGNORECASE) is not None

    def _canon_catalog_id(s):
        s2 = re.sub(r"\s+", "", s.strip().lower())
        if not s2:
            return None
        if re.match(r"^[a-z0-9][a-z0-9_.-]*$", s2) is None:
            return None
        return s2

    def _canon_url(u):
        from urllib.parse import urlsplit, urlunsplit
        try:
            sp = urlsplit(u.strip())
        except Exception:
            return None, "invalid URL"
        scheme = (sp.scheme or "").lower()
        if scheme not in ("http", "https"):
            return None, "invalid URL scheme (must be http/https)"
        if not sp.netloc:
            return None, "missing host"
        if sp.fragment:
            return None, "invalid URL for spec source: fragments are not permitted"
        if sp.query:
            return None, "canonical URL mismatch: query params not allowed for spec source"
        netloc = sp.netloc
        if ":" in netloc:
            host, port = netloc.rsplit(":", 1)
            if (scheme == "http" and port == "80") or (scheme == "https" and port == "443"):
                netloc = host
        path2 = sp.path or "/"
        return urlunsplit((scheme, netloc, path2, "", "")), None

    def _detect_and_normalize(input_id):
        s = input_id.strip()
        if _is_probable_url(s):
            canon, err = _canon_url(s)
            if canon:
                return "url", canon, None
            return "url", None, err or "invalid URL"
        cid = _canon_catalog_id(s)
        if cid:
            return "catalog_id", cid, None
        return "unknown", None, "unrecognized identifier: not a catalog key and not a valid http(s) URL"

    detected_kind, normalized, norm_err = _detect_and_normalize(raw_id)
    now = _utcnow_z()

    # find spec
    spec_row = None
    for srow in api_specs:
        if isinstance(srow, dict) and srow.get("id") == raw_id:
            spec_row = srow
            break
    if spec_row is None and normalized:
        for srow in api_specs:
            if not isinstance(srow, dict):
                continue
            if srow.get("resolved_canonical_id") == normalized:
                spec_row = srow
                break
            if detected_kind == "catalog_id" and srow.get("source_kind") == "catalog_id" and (srow.get("external_id") or "").lower() == normalized:
                spec_row = srow
                break
            if detected_kind == "url" and srow.get("source_kind") == "url" and srow.get("source_url") == normalized:
                spec_row = srow
                break

    # upsert a resolution attempt for observability
    def _upsert_resolution(api_spec_id, resolved, resolution_error):
        # best effort: reuse by normalized_input if available
        existing = None
        if normalized:
            for r in res_rows:
                if isinstance(r, dict) and r.get("normalized_input") == normalized:
                    existing = r
                    break
        if existing is None:
            existing = {
                "id": _new_id("oamcp_res"),
                "input_id": raw_id,
                "normalized_input": normalized or raw_id,
                "detected_kind": detected_kind,
                "api_spec_id": api_spec_id,
                "resolved": bool(resolved),
                "resolution_error": resolution_error,
                "created_at": now,
                "updated_at": now
            }
            res_rows.append(existing)
        else:
            prev_kind = existing.get("detected_kind")
            if prev_kind == "unknown" and detected_kind in ("catalog_id", "url"):
                existing["detected_kind"] = detected_kind
            existing["input_id"] = raw_id
            existing["normalized_input"] = normalized or existing.get("normalized_input") or raw_id
            existing["api_spec_id"] = api_spec_id
            existing["resolved"] = bool(resolved)
            existing["resolution_error"] = resolution_error
            existing["updated_at"] = now
        _save_rows("api_resolutions.json", res_cont, res_rows)
        return existing

    if norm_err and detected_kind in ("url", "unknown"):
        res_row = _upsert_resolution(None, False, norm_err)
        _log("error", resolution_id=res_row.get("id"), error_code="NOT_FOUND")
        return _err("NOT_FOUND", "API identifier could not be resolved to an existing spec.", resolution=res_row)

    if spec_row is None:
        msg = "catalog lookup miss: no matching API key; provide catalog id or spec URL" if detected_kind == "catalog_id" else "API identifier could not be resolved to an existing spec."
        res_row = _upsert_resolution(None, False, msg)
        _log("error", resolution_id=res_row.get("id"), error_code="NOT_FOUND")
        return _err("NOT_FOUND", "API identifier could not be resolved to an existing spec.", resolution=res_row)

    res_row = _upsert_resolution(spec_row.get("id"), True, None)
    api_spec_id = spec_row.get("id")
    resolution_id = res_row.get("id")

    # readiness: this tool says it refuses when not servable, unless refresh requested.
    # We do not perform network fetch here; we just return a clear error if not ready and refresh requested is true.
    if spec_row.get("status") != "ready":
        if refresh:
            _log("error", resolution_id=resolution_id, api_spec_id=api_spec_id, error_code="INVALID_TRANSITION",
                 details={"spec_status": spec_row.get("status"), "refresh": True})
            return _err("INVALID_TRANSITION", "API spec is not ready; refresh requested but this server cannot fetch/parse in this tool.", api_spec=spec_row, resolution=res_row)
        _log("error", resolution_id=resolution_id, api_spec_id=api_spec_id, error_code="INVALID_TRANSITION",
             details={"spec_status": spec_row.get("status")})
        return _err("INVALID_TRANSITION", "API spec is not ready to list operations.", api_spec=spec_row, resolution=res_row)

    # load ops and filter
    ops_cont, ops_rows = _load_rows("api_operations.json")
    rows = [r for r in ops_rows if isinstance(r, dict) and r.get("api_spec_id") == api_spec_id]

    if not includeRemoved:
        rows = [r for r in rows if r.get("status") != "removed"]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if method is not None:
        rows = [r for r in rows if r.get("method") == method]
    if path is not None:
        rows = [r for r in rows if r.get("path") == path]
    if tag is not None:
        rows = [r for r in rows if isinstance(r.get("tags"), list) and tag in r.get("tags")]

    if query is not None and query.strip():
        q = query.strip().lower()
        def _hay(r):
            parts = []
            for k in ("operation_id", "summary", "path", "description", "route_key"):
                v = r.get(k)
                if isinstance(v, str) and v:
                    parts.append(v.lower())
            tagsv = r.get("tags")
            if isinstance(tagsv, list):
                parts.append(" ".join([str(x).lower() for x in tagsv if x is not None]))
            return " \n".join(parts)
        rows = [r for r in rows if q in _hay(r)]

    total = len(rows)

    # sort
    reverse = (order == "desc")
    if orderBy == "updated_at":
        rows.sort(key=lambda r: _parse_dt(r.get("updated_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc), reverse=reverse)
    elif orderBy == "operation_id":
        rows.sort(key=lambda r: (r.get("operation_id") or ""), reverse=reverse)
    elif orderBy == "method":
        rows.sort(key=lambda r: (r.get("method") or ""), reverse=reverse)
    else:  # path
        rows.sort(key=lambda r: (r.get("path") or "", r.get("method") or ""), reverse=reverse)

    # paginate
    start = (page - 1) * pageSize
    end = start + pageSize
    page_items = rows[start:end]
    has_more = end < total

    _log("ok", resolution_id=resolution_id, api_spec_id=api_spec_id)
    return {
        "api_spec_id": api_spec_id,
        "resolution": res_row,
        "page": page,
        "page_size": pageSize,
        "total": total,
        "has_more": has_more,
        "items": page_items
    }

def resolveApiId(inputId, createIfMissing=None, **_extra):
    import json, os, datetime, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0238000" if __import__("os").path.isdir("./environment_mix/0238000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    def _utcnow_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _load_rows(filename):
        data = _load(filename)
        if isinstance(data, dict):
            rows = data.get("rows")
            if isinstance(rows, list):
                return data, rows
            return {"rows": []}, []
        if isinstance(data, list):
            return {"rows": data}, data
        return {"rows": []}, []

    def _save_rows(filename, container, rows):
        if isinstance(container, dict):
            container["rows"] = rows
            _save(filename, container)
        else:
            _save(filename, rows)

    def _new_id(prefix):
        import os as _os, time as _time, secrets as _secrets
        return f"{prefix}_{int(_time.time()*1000)}_{_os.getpid()}_{_secrets.token_hex(8)}"

    def _ensure_logs():
        cont, rows = _load_rows("request_logs.json")
        if not isinstance(rows, list):
            rows = []
        return cont, rows

    def _log(status, resolution_id=None, api_spec_id=None, error_code=None, details=None):
        cont, rows = _ensure_logs()
        latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
        rows.append({
            "id": _new_id("req"),
            "endpoint": "resolveApiId",
            "timestamp": _utcnow_z(),
            "latency_ms": latency_ms,
            "status": status,
            "resolution_id": resolution_id,
            "api_spec_id": api_spec_id,
            "error_code": error_code,
            "details": details or {}
        })
        _save_rows("request_logs.json", cont, rows)

    if createIfMissing is None:
        createIfMissing = True
    if not isinstance(createIfMissing, bool):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'createIfMissing' (must be boolean).")
    if not isinstance(inputId, str) or not inputId.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'inputId' is required and must be a non-empty string.")

    raw = inputId.strip()

    def _is_probable_url(s):
        return re.match(r"^https?://", s.strip(), re.IGNORECASE) is not None

    def _canon_catalog_id(s):
        s2 = re.sub(r"\s+", "", s.strip().lower())
        if not s2:
            return None
        if re.match(r"^[a-z0-9][a-z0-9_.-]{0,255}$", s2) is None:
            return None
        return s2

    def _canon_url(u):
        from urllib.parse import urlsplit, urlunsplit
        try:
            sp = urlsplit(u.strip())
        except Exception:
            return None, "invalid URL for spec source"
        scheme = (sp.scheme or "").lower()
        if scheme not in ("http", "https"):
            return None, "fetch disallowed by policy: http scheme not permitted (https required)" if scheme == "http" else "invalid URL scheme (must be http/https)"
        if not sp.netloc:
            return None, "invalid URL for spec source: missing host"
        if sp.fragment:
            return None, "invalid URL for spec source: fragments are not permitted"
        if sp.query:
            return None, "blocked by canonicalization: query string not allowed for raw spec URLs"
        netloc = sp.netloc
        if ":" in netloc:
            host, port = netloc.rsplit(":", 1)
            if (scheme == "http" and port == "80") or (scheme == "https" and port == "443"):
                netloc = host
        path = sp.path or "/"
        return urlunsplit((scheme, netloc, path, "", "")), None

    # detect kind + normalize
    detected_kind = "unknown"
    normalized = None
    err = None
    if _is_probable_url(raw):
        detected_kind = "url"
        normalized, err = _canon_url(raw)
    else:
        cid = _canon_catalog_id(raw)
        if cid:
            detected_kind = "catalog_id"
            normalized = cid
        else:
            detected_kind = "unknown"
            normalized = raw.strip().lower()
            err = "unrecognized identifier: not a catalog key and not a valid http(s) URL"

    res_cont, res_rows = _load_rows("api_resolutions.json")
    specs_cont, specs_rows = _load_rows("api_specs.json")

    # attempt to map to existing spec without fetching/parsing
    spec_row = None
    # allow internal spec id to be "resolved" immediately
    for srow in specs_rows:
        if isinstance(srow, dict) and srow.get("id") == raw:
            spec_row = srow
            break

    if spec_row is None and normalized and detected_kind != "unknown":
        for srow in specs_rows:
            if not isinstance(srow, dict):
                continue
            if srow.get("resolved_canonical_id") == normalized:
                spec_row = srow
                break
            if detected_kind == "catalog_id" and srow.get("source_kind") == "catalog_id" and (srow.get("external_id") or "").lower() == normalized:
                spec_row = srow
                break
            if detected_kind == "url" and srow.get("source_kind") == "url" and srow.get("source_url") == normalized:
                spec_row = srow
                break

    # find existing resolution row (prefer normalized_input)
    existing = None
    for r in res_rows:
        if not isinstance(r, dict):
            continue
        if normalized and r.get("normalized_input") == normalized:
            existing = r
            break
    if existing is None:
        for r in res_rows:
            if not isinstance(r, dict):
                continue
            if r.get("input_id") == raw:
                existing = r
                break

    now = _utcnow_z()
    resolved = bool(spec_row is not None)
    api_spec_id = spec_row.get("id") if spec_row else None
    resolution_error = None
    if not resolved:
        resolution_error = err or ("catalog lookup miss: no matching API key; provide catalog id or spec URL" if detected_kind == "catalog_id" else "API identifier could not be resolved to an existing spec.")

    changed = False
    if existing is None:
        if not createIfMissing:
            # still log call, but return a transient response without creating
            _log("ok", resolution_id=None, api_spec_id=api_spec_id)
            return {
                "resolution": {
                    "id": None,
                    "input_id": raw,
                    "normalized_input": normalized or raw,
                    "detected_kind": detected_kind,
                    "api_spec_id": api_spec_id,
                    "resolved": resolved,
                    "resolution_error": resolution_error,
                    "created_at": now,
                    "updated_at": now
                }
            }
        existing = {
            "id": _new_id("oamcp_res"),
            "input_id": raw,
            "normalized_input": normalized or raw,
            "detected_kind": detected_kind,
            "api_spec_id": api_spec_id,
            "resolved": resolved,
            "resolution_error": resolution_error,
            "created_at": now,
            "updated_at": now
        }
        res_rows.append(existing)
        changed = True
    else:
        # lifecycle: unknown -> catalog_id/url allowed
        prev_kind = existing.get("detected_kind")
        if prev_kind == "unknown" and detected_kind in ("catalog_id", "url"):
            existing["detected_kind"] = detected_kind
        existing["input_id"] = raw
        existing["normalized_input"] = normalized or existing.get("normalized_input") or raw
        existing["api_spec_id"] = api_spec_id
        existing["resolved"] = resolved
        existing["resolution_error"] = resolution_error
        existing["updated_at"] = now
        changed = True

    if changed:
        _save_rows("api_resolutions.json", res_cont, res_rows)

    _log("ok", resolution_id=existing.get("id"), api_spec_id=api_spec_id)
    return {"resolution": existing}

def refreshApiSpec(id, mode=None, allowNetworkFetch=None, **_extra):
    import json, os, datetime, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0238000" if __import__("os").path.isdir("./environment_mix/0238000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    def _utcnow_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _load_rows(filename):
        data = _load(filename)
        if isinstance(data, dict):
            rows = data.get("rows")
            if isinstance(rows, list):
                return data, rows
            return {"rows": []}, []
        if isinstance(data, list):
            return {"rows": data}, data
        return {"rows": []}, []

    def _save_rows(filename, container, rows):
        if isinstance(container, dict):
            container["rows"] = rows
            _save(filename, container)
        else:
            _save(filename, rows)

    def _new_id(prefix):
        import os as _os, time as _time, secrets as _secrets
        return f"{prefix}_{int(_time.time()*1000)}_{_os.getpid()}_{_secrets.token_hex(8)}"

    def _ensure_logs():
        cont, rows = _load_rows("request_logs.json")
        if not isinstance(rows, list):
            rows = []
        return cont, rows

    def _log(status, resolution_id=None, api_spec_id=None, error_code=None, details=None):
        cont, rows = _ensure_logs()
        latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
        rows.append({
            "id": _new_id("req"),
            "endpoint": "refreshApiSpec",
            "timestamp": _utcnow_z(),
            "latency_ms": latency_ms,
            "status": status,
            "resolution_id": resolution_id,
            "api_spec_id": api_spec_id,
            "error_code": error_code,
            "details": details or {}
        })
        _save_rows("request_logs.json", cont, rows)

    # validate
    if not isinstance(id, str) or not id.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'id' is required and must be a non-empty string.")
    if mode is None:
        mode = "force"
    if not isinstance(mode, str) or mode not in ("force", "if_stale", "if_not_ready"):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'mode' (must be one of force/if_stale/if_not_ready).")
    if allowNetworkFetch is None:
        allowNetworkFetch = True
    if not isinstance(allowNetworkFetch, bool):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'allowNetworkFetch' (must be boolean).")

    raw_id = id.strip()

    # resolve like other tools: accept direct internal id
    specs_cont, specs_rows = _load_rows("api_specs.json")
    res_cont, res_rows = _load_rows("api_resolutions.json")

    def _is_probable_url(s):
        return re.match(r"^https?://", s.strip(), re.IGNORECASE) is not None

    def _canon_catalog_id(s):
        s2 = re.sub(r"\s+", "", s.strip().lower())
        if not s2:
            return None
        if re.match(r"^[a-z0-9][a-z0-9_.-]*$", s2) is None:
            return None
        return s2

    def _canon_url(u):
        from urllib.parse import urlsplit, urlunsplit
        try:
            sp = urlsplit(u.strip())
        except Exception:
            return None, "invalid URL"
        scheme = (sp.scheme or "").lower()
        if scheme not in ("http", "https"):
            return None, "invalid URL scheme (must be http/https)"
        if not sp.netloc:
            return None, "missing host"
        if sp.fragment:
            return None, "invalid URL for spec source: fragments are not permitted"
        if sp.query:
            return None, "canonical URL mismatch: query params not allowed for spec source"
        netloc = sp.netloc
        if ":" in netloc:
            host, port = netloc.rsplit(":", 1)
            if (scheme == "http" and port == "80") or (scheme == "https" and port == "443"):
                netloc = host
        path = sp.path or "/"
        return urlunsplit((scheme, netloc, path, "", "")), None

    detected_kind = "unknown"
    normalized = None
    norm_err = None
    if _is_probable_url(raw_id):
        detected_kind = "url"
        normalized, norm_err = _canon_url(raw_id)
    else:
        cid = _canon_catalog_id(raw_id)
        if cid:
            detected_kind = "catalog_id"
            normalized = cid
        else:
            detected_kind = "unknown"
            norm_err = "unrecognized identifier: not a catalog key and not a valid http(s) URL"

    # find spec row
    spec_row = None
    for srow in specs_rows:
        if isinstance(srow, dict) and srow.get("id") == raw_id:
            spec_row = srow
            break
    if spec_row is None and normalized:
        for srow in specs_rows:
            if not isinstance(srow, dict):
                continue
            if srow.get("resolved_canonical_id") == normalized:
                spec_row = srow
                break
            if detected_kind == "catalog_id" and srow.get("source_kind") == "catalog_id" and (srow.get("external_id") or "").lower() == normalized:
                spec_row = srow
                break
            if detected_kind == "url" and srow.get("source_kind") == "url" and srow.get("source_url") == normalized:
                spec_row = srow
                break

    now = _utcnow_z()

    # upsert resolution attempt
    def _upsert_resolution(api_spec_id, resolved, resolution_error):
        existing = None
        if normalized:
            for r in res_rows:
                if isinstance(r, dict) and r.get("normalized_input") == normalized:
                    existing = r
                    break
        if existing is None:
            for r in res_rows:
                if isinstance(r, dict) and r.get("input_id") == raw_id:
                    existing = r
                    break
        if existing is None:
            existing = {
                "id": _new_id("oamcp_res"),
                "input_id": raw_id,
                "normalized_input": normalized or raw_id.lower(),
                "detected_kind": detected_kind,
                "api_spec_id": api_spec_id,
                "resolved": bool(resolved),
                "resolution_error": resolution_error,
                "created_at": now,
                "updated_at": now
            }
            res_rows.append(existing)
        else:
            prev_kind = existing.get("detected_kind")
            if prev_kind == "unknown" and detected_kind in ("catalog_id", "url"):
                existing["detected_kind"] = detected_kind
            existing["input_id"] = raw_id
            existing["normalized_input"] = normalized or existing.get("normalized_input") or raw_id.lower()
            existing["api_spec_id"] = api_spec_id
            existing["resolved"] = bool(resolved)
            existing["resolution_error"] = resolution_error
            existing["updated_at"] = now
        _save_rows("api_resolutions.json", res_cont, res_rows)
        return existing

    if spec_row is None:
        msg = norm_err or ("catalog lookup miss: no matching API key; provide catalog id or spec URL" if detected_kind == "catalog_id" else "API identifier could not be resolved to an existing spec.")
        res_row = _upsert_resolution(None, False, msg)
        _log("error", resolution_id=res_row.get("id"), error_code="NOT_FOUND")
        return _err("NOT_FOUND", "API identifier could not be resolved to an existing spec.", resolution=res_row)

    # enforce allowNetworkFetch for URL sources (we cannot actually fetch, but must apply the policy)
    if spec_row.get("source_kind") == "url" and not allowNetworkFetch:
        res_row = _upsert_resolution(spec_row.get("id"), True, None)
        _log("error", resolution_id=res_row.get("id"), api_spec_id=spec_row.get("id"), error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Network fetch is disabled (allowNetworkFetch=false) for url-based specs.", api_spec=spec_row, resolution=res_row)

    # apply mode rules
    current_status = spec_row.get("status")
    if mode == "if_stale":
        # we don't have a dedicated stale flag on spec; treat non-ready as needing refresh
        if current_status == "ready":
            res_row = _upsert_resolution(spec_row.get("id"), True, None)
            _log("ok", resolution_id=res_row.get("id"), api_spec_id=spec_row.get("id"), details={"mode": mode, "no_change": True})
            return {"api_spec": spec_row, "resolution": res_row, "refreshed": False}
    if mode == "if_not_ready":
        if current_status == "ready":
            res_row = _upsert_resolution(spec_row.get("id"), True, None)
            _log("ok", resolution_id=res_row.get("id"), api_spec_id=spec_row.get("id"), details={"mode": mode, "no_change": True})
            return {"api_spec": spec_row, "resolution": res_row, "refreshed": False}

    # transition to fetching if allowed by lifecycle
    transitions = {
        "new": ["fetching", "disabled"],
        "fetching": ["ready", "error", "disabled"],
        "ready": ["fetching", "disabled"],
        "error": ["fetching", "disabled"],
        "disabled": ["fetching"],
    }
    if current_status not in transitions or "fetching" not in transitions[current_status]:
        res_row = _upsert_resolution(spec_row.get("id"), True, None)
        _log("error", resolution_id=res_row.get("id"), api_spec_id=spec_row.get("id"), error_code="INVALID_TRANSITION",
             details={"from": current_status, "to": "fetching"})
        return _err("INVALID_TRANSITION", "Cannot transition api_specs.status to 'fetching' from current status.", api_spec=spec_row, from_status=current_status, to_status="fetching", resolution=res_row)

    # perform transition and mark fetch attempt timestamp; since offline, we do not actually fetch.
    spec_row["status"] = "fetching"
    spec_row["last_fetched_at"] = now
    spec_row["updated_at"] = now
    # keep previous parse_error unless you want to clear on refetch attempt; do not erase real error without new parse
    _save_rows("api_specs.json", specs_cont, specs_rows)

    res_row = _upsert_resolution(spec_row.get("id"), True, None)

    # Without network/fetch parser, spec will remain fetching; that's still a real mutation and observable.
    _log("ok", resolution_id=res_row.get("id"), api_spec_id=spec_row.get("id"), details={"mode": mode, "set_status": "fetching"})
    return {"api_spec": spec_row, "resolution": res_row, "refreshed": True}

