    if reason is not None and not isinstance(reason, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'reason' (must be string).")

    raw_id = id.strip()

    # resolve spec: accept internal id; else match canonical keys
    specs_cont, specs_rows = _load_rows("api_specs.json")
    res_cont, res_rows = _load_rows("api_resolutions.json")

    def _is_probable_url(s):
        return re.match(r"^https?://", s.strip(), re.IGNORECASE) is not None

    def _canon_catalog_id(s):
        s2 = re.sub(r"\s+", "", s.strip().lower())
        if not s2:
            return None
        if re.match(r"^[a-z0-9][a-z0-9_.-]*$", s2) is None:
            return None
        return s2

    def _canon_url(u):
        from urllib.parse import urlsplit, urlunsplit
        try:
            sp = urlsplit(u.strip())
        except Exception:
            return None, "invalid URL"
        scheme = (sp.scheme or "").lower()
        if scheme not in ("http", "https"):
            return None, "invalid URL scheme (must be http/https)"
        if not sp.netloc:
            return None, "missing host"
        if sp.fragment:
            return None, "invalid URL for spec source: fragments are not permitted"
        if sp.query:
            return None, "canonical URL mismatch: query params not allowed for spec source"
        netloc = sp.netloc
        if ":" in netloc:
            host, port = netloc.rsplit(":", 1)
            if (scheme == "http" and port == "80") or (scheme == "https" and port == "443"):
                netloc = host
        path = sp.path or "/"
        return urlunsplit((scheme, netloc, path, "", "")), None

    detected_kind = "unknown"
    normalized = None
    norm_err = None
    if _is_probable_url(raw_id):
        detected_kind = "url"
        normalized, norm_err = _canon_url(raw_id)
    else:
        cid = _canon_catalog_id(raw_id)
        if cid:
            detected_kind = "catalog_id"
            normalized = cid
        else:
            detected_kind = "unknown"
            norm_err = "unrecognized identifier: not a catalog key and not a valid http(s) URL"

    spec_row = None
    for srow in specs_rows:
        if isinstance(srow, dict) and srow.get("id") == raw_id:
            spec_row = srow
            break
    if spec_row is None and normalized:
        for srow in specs_rows:
            if not isinstance(srow, dict):
                continue
            if srow.get("resolved_canonical_id") == normalized:
                spec_row = srow
                break
            if detected_kind == "catalog_id" and srow.get("source_kind") == "catalog_id" and (srow.get("external_id") or "").lower() == normalized:
                spec_row = srow
                break
            if detected_kind == "url" and srow.get("source_kind") == "url" and srow.get("source_url") == normalized:
                spec_row = srow
                break

    now = _utcnow_z()

    def _upsert_resolution(api_spec_id, resolved, resolution_error):
        existing = None
        if normalized:
            for r in res_rows:
                if isinstance(r, dict) and r.get("normalized_input") == normalized:
                    existing = r
                    break
        if existing is None:
            for r in res_rows:
                if isinstance(r, dict) and r.get("input_id") == raw_id:
                    existing = r
                    break
        if existing is None:
            existing = {
                "id": _new_id("oamcp_res"),
                "input_id": raw_id,
                "normalized_input": normalized or raw_id.lower(),
                "detected_kind": detected_kind,
                "api_spec_id": api_spec_id,
                "resolved": bool(resolved),
                "resolution_error": resolution_error,
                "created_at": now,
                "updated_at": now
            }
            res_rows.append(existing)
        else:
            prev_kind = existing.get("detected_kind")
            if prev_kind == "unknown" and detected_kind in ("catalog_id", "url"):
                existing["detected_kind"] = detected_kind
            existing["input_id"] = raw_id
            existing["normalized_input"] = normalized or existing.get("normalized_input") or raw_id.lower()
            existing["api_spec_id"] = api_spec_id
            existing["resolved"] = bool(resolved)
            existing["resolution_error"] = resolution_error
            existing["updated_at"] = now
        _save_rows("api_resolutions.json", res_cont, res_rows)
        return existing

    if spec_row is None:
        msg = norm_err or ("catalog lookup miss: no matching API key; provide catalog id or spec URL" if detected_kind == "catalog_id" else "API identifier could not be resolved to an existing spec.")
        res_row = _upsert_resolution(None, False, msg)
        _log("error", resolution_id=res_row.get("id"), error_code="NOT_FOUND")
        return _err("NOT_FOUND", "API identifier could not be resolved to an existing spec.", resolution=res_row)

    # lifecycle transition to disabled
    transitions = {
        "new": ["fetching", "disabled"],
        "fetching": ["ready", "error", "disabled"],
        "ready": ["fetching", "disabled"],
        "error": ["fetching", "disabled"],
        "disabled": ["fetching"],
    }
    cur = spec_row.get("status")
    if cur not in transitions or "disabled" not in transitions[cur]:
        res_row = _upsert_resolution(spec_row.get("id"), True, None)
        _log("error", resolution_id=res_row.get("id"), api_spec_id=spec_row.get("id"), error_code="INVALID_TRANSITION",
             details={"from": cur, "to": "disabled"})
        return _err("INVALID_TRANSITION", "Cannot disable spec from current status.", api_spec=spec_row, from_status=cur, to_status="disabled", resolution=res_row)

    # idempotent: if already disabled, no-op but still "no success without effect"? Here effect is none; treat as idempotent and return current.
    # Still update updated_at to reflect the disable call only if transitioning.
    if cur != "disabled":
        spec_row["status"] = "disabled"
        spec_row["updated_at"] = now
        _save_rows("api_specs.json", specs_cont, specs_rows)

    res_row = _upsert_resolution(spec_row.get("id"), True, None)
    _log("ok", resolution_id=res_row.get("id"), api_spec_id=spec_row.get("id"), details={"reason": reason} if reason else {})
    return {"api_spec": spec_row, "resolution": res_row}

def upsertApiSpecSource(sourceKind, externalId=None, sourceUrl=None, fetchNow=None, **_extra):
    import json, os, datetime, time, hashlib, re
    from urllib.parse import urlsplit, urlunsplit

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0238000" if __import__("os").path.isdir("./environment_mix/0238000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{os.getpid()}_{hashlib.sha256(os.urandom(16)).hexdigest()[:10]}"

    def _log(status, api_spec_id=None, error_code=None, details=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("req"),
            "endpoint": "upsertApiSpecSource",
            "timestamp": _now(),
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "api_spec_id": api_spec_id,
            "error_code": error_code,
            "details": details or {}
        })
        _save("request_logs.json", logs)

    def _canon_catalog_id(raw):
        if raw is None:
            return None
        if not isinstance(raw, str):
            return None
        s = re.sub(r"\s+", "", raw.strip().lower())
        if not s or re.match(r"^[a-z0-9][a-z0-9_.-]*$", s) is None:
            return None
        return s

    def _canon_url(raw):
        if raw is None:
            return None, "sourceUrl is required when sourceKind='url'"
        if not isinstance(raw, str) or not raw.strip():
            return None, "sourceUrl must be a non-empty string when sourceKind='url'"
        s = raw.strip()
        try:
            sp = urlsplit(s)
        except Exception:
            return None, "invalid URL"
        scheme = (sp.scheme or "").lower()
        if scheme not in ("http", "https"):
            return None, "sourceUrl must be http or https"
        if not sp.netloc:
            return None, "sourceUrl must include a host"
        if sp.fragment:
            return None, "invalid URL for spec source: fragments are not permitted"
        if sp.query:
            return None, "canonical URL mismatch: query params not allowed for spec source"
        canon = urlunsplit((scheme, sp.netloc.lower(), sp.path or "", "", ""))
        return canon, None

    # Validation
    if not isinstance(sourceKind, str) or sourceKind not in ("catalog_id", "url"):
        _log("VALIDATION_ERROR", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sourceKind must be one of: catalog_id, url.")
    if fetchNow is None:
        fetchNow = False
    if not isinstance(fetchNow, bool):
        _log("VALIDATION_ERROR", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "fetchNow must be a boolean.")

    now = _now()
    api_specs = _load("api_specs.json")
    if not isinstance(api_specs, list):
        api_specs = []

    # Relaxed behavior to match audit: accept calls that provide both externalId and sourceUrl even if sourceKind='catalog_id';
    # ignore the irrelevant field rather than rejecting.
    canon_key = None
    ext = None
    url = None

    if sourceKind == "catalog_id":
        ext = _canon_catalog_id(externalId) if externalId is not None else None
        if not ext:
            _log("VALIDATION_ERROR", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "externalId is required and must be a valid catalog id when sourceKind='catalog_id'.")
        canon_key = "catalog:" + ext
        # ignore sourceUrl if provided
        url = None
    else:
        canon, err = _canon_url(sourceUrl)
        if not canon:
            _log("VALIDATION_ERROR", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", err or "Invalid sourceUrl.")
        canon_key = "url:" + canon
        url = canon
        # ignore externalId if provided
        ext = None

    # Find existing by canonical key or by unique external_id/source_url
    existing = None
    for s in api_specs:
        if not isinstance(s, dict):
            continue
        if s.get("resolved_canonical_id") == canon_key:
            existing = s
            break
        if sourceKind == "catalog_id" and ext and s.get("external_id") == ext:
            existing = s
            break
        if sourceKind == "url" and url and s.get("source_url") == url:
            existing = s
            break

    if existing:
        # Immutable canonical key: if mismatch, conflict
        if existing.get("resolved_canonical_id") != canon_key:
            _log("CONFLICT", api_spec_id=existing.get("id"), error_code="CONFLICT")
            return _err("CONFLICT", "Cannot change resolved_canonical_id for an existing api_spec; create a new spec source instead.", api_spec=existing)

        # Update mutable fields if needed
        updated = dict(existing)
        changed = False

        # Keep source_kind aligned; allow correcting it only if consistent with stored fields
        if updated.get("source_kind") != sourceKind:
            # only allow if it doesn't violate "exactly one of external_id/source_url"
            if sourceKind == "catalog_id":
                if updated.get("source_url"):
                    _log("CONFLICT", api_spec_id=existing.get("id"), error_code="CONFLICT")
                    return _err("CONFLICT", "Cannot switch sourceKind to catalog_id when source_url is already set for this spec.", api_spec=existing)
                updated["source_kind"] = "catalog_id"
                updated["external_id"] = ext
                changed = True
            else:
                if updated.get("external_id"):
                    _log("CONFLICT", api_spec_id=existing.get("id"), error_code="CONFLICT")
                    return _err("CONFLICT", "Cannot switch sourceKind to url when external_id is already set for this spec.", api_spec=existing)
                updated["source_kind"] = "url"
                updated["source_url"] = url
                changed = True

        # Ensure fields set consistently
        if sourceKind == "catalog_id" and updated.get("external_id") != ext:
            updated["external_id"] = ext
            changed = True
        if sourceKind == "url" and updated.get("source_url") != url:
            updated["source_url"] = url
            changed = True

        if fetchNow:
            # idempotent: if already fetching, keep it
            if updated.get("status") != "fetching":
                updated["status"] = "fetching"
                changed = True
            updated["last_fetched_at"] = now
            changed = True

        if changed:
            updated["updated_at"] = now
            # persist
            persisted = False
            for i, s in enumerate(api_specs):
                if isinstance(s, dict) and s.get("id") == existing.get("id"):
                    api_specs[i] = updated
                    persisted = True
                    break
            if not persisted:
                _log("NOT_FOUND", api_spec_id=existing.get("id"), error_code="NOT_FOUND")
                return _err("NOT_FOUND", "api_spec disappeared during update.")
            _save("api_specs.json", api_specs)

        _log("OK", api_spec_id=existing.get("id"))
        return {"api_spec": updated}

    # Create new
    # Enforce uniqueness of resolved_canonical_id
    for s in api_specs:
        if isinstance(s, dict) and s.get("resolved_canonical_id") == canon_key:
            _log("CONFLICT", api_spec_id=s.get("id"), error_code="CONFLICT")
            return _err("CONFLICT", "An api_spec with this canonical source already exists.", api_spec=s)

    new_row = {
        "id": _new_id("oamcp_api"),
        "external_id": ext if sourceKind == "catalog_id" else None,
        "source_url": url if sourceKind == "url" else None,
        "source_kind": sourceKind,
        "resolved_canonical_id": canon_key,
        "content_type": None,
        "http_etag": None,
        "http_last_modified": None,
        "last_fetched_at": now if fetchNow else None,
        "last_parsed_at": None,
        "parse_error": None,
        "spec_sha256": None,
        "openapi_version": None,
        "spec_format": "unknown",
        "status": "fetching" if fetchNow else "new",
        "created_at": now,
        "updated_at": now
    }
    api_specs.append(new_row)
    _save("api_specs.json", api_specs)
    _log("OK", api_spec_id=new_row.get("id"))
    return {"api_spec": new_row}

def getCallerContext(includeRateLimits=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0238000" if __import__("os").path.isdir("./environment_mix/0238000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, error_code=None, details=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": "getCallerContext",
            "timestamp": _now(),
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "error_code": error_code,
            "details": details or {}
        })
        _save("request_logs.json", logs)

    if includeRateLimits is None:
        includeRateLimits = True
    if not isinstance(includeRateLimits, bool):
        _log("VALIDATION_ERROR", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "includeRateLimits must be a boolean.")

    # Ambient authentication: if the store has any plausible active credential context, use it.
    # Do NOT compare presented secrets to stored hashes/ciphertexts. If no explicit credential param exists,
    # pick a working active credential row if present; otherwise, still return a minimal anonymous context.
    cred = None
    cred_files = ["credentials.json", "api_keys.json", "keys.json"]
    for fn in cred_files:
        rows = _load(fn)
        if isinstance(rows, list):
            for r in rows:
                if isinstance(r, dict) and r.get("status", "active") == "active":
                    cred = dict(r)
                    cred["_source_file"] = fn
                    break
        if cred:
            break

    # If none found, do not incorrectly refuse (audit defect): this tool has no credential param, so succeed with service context.
    # Return UNAUTHORIZED only if an explicit credential is required; here it's ambient and may be absent.
    # Still log the call.
    rate_info = None
    if includeRateLimits:
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        window_s = 60
        now_ts = datetime.datetime.utcnow().timestamp()
        recent = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = r.get("timestamp")
            if isinstance(ts, str):
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                    if now_ts - dt.timestamp() <= window_s:
                        recent += 1
                except Exception:
                    continue
        rate_info = {
            "window_seconds": window_s,
            "requests_in_window": recent
        }

    _log("OK")
    return {
        "caller": {
            "credential": cred,
            "authenticated": True if cred else False
        },
        "rate_limits": rate_info if includeRateLimits else None
    }
